const payload = $json.body ?? $json;

function firstDefined(...values) {
  return values.find((value) => value !== undefined && value !== null);
}

function normalizeText(message) {
  return firstDefined(
    message?.conversation,
    message?.extendedTextMessage?.text,
    message?.imageMessage?.caption,
    message?.videoMessage?.caption,
    message?.documentMessage?.caption,
    ''
  );
}

function extractAudio(message) {
  return {
    url: firstDefined(message?.audioMessage?.url, message?.pttMessage?.url, null),
    base64: firstDefined(message?.audioMessage?.base64, message?.pttMessage?.base64, null),
    mimeType: firstDefined(message?.audioMessage?.mimetype, message?.pttMessage?.mimetype, 'audio/ogg')
  };
}

function stripHtml(value) {
  return value ? value.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim() : '';
}

function detectProductIntent(value) {
  if (!value) {
    return false;
  }

  return /(product|products|price|cost|stock|available|availability|catalog|item|buy|purchase|details)/i.test(value);
}

async function fetchWooCommerceProducts(query, baseUrl, consumerKey, consumerSecret) {
  const endpoint = new URL(`${baseUrl.replace(/\/$/, '')}/wp-json/wc/v3/products`);
  endpoint.searchParams.set('search', query);
  endpoint.searchParams.set('per_page', '3');
  endpoint.searchParams.set('status', 'publish');

  const credentials = Buffer.from(`${consumerKey}:${consumerSecret}`).toString('base64');
  const response = await fetch(endpoint, {
    headers: {
      Authorization: `Basic ${credentials}`
    }
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`WooCommerce product lookup failed: ${response.status} ${errorText}`);
  }

  const products = await response.json();
  if (!Array.isArray(products)) {
    return [];
  }

  return products.map((product) => ({
    id: product.id,
    name: product.name,
    price: product.price_html || product.price || product.regular_price || '',
    stockStatus: product.stock_status || 'unknown',
    permalink: product.permalink || '',
    shortDescription: stripHtml(product.short_description || product.description || '').slice(0, 220)
  }));
}

function formatProductContext(products) {
  if (!products.length) {
    return 'WooCommerce product lookup returned no matching products.';
  }

  return products
    .map((product, index) => [
      `${index + 1}. ${product.name}`,
      `Price: ${product.price || 'not available'}`,
      `Stock: ${product.stockStatus}`,
      product.shortDescription ? `Summary: ${product.shortDescription}` : null,
      product.permalink ? `Link: ${product.permalink}` : null
    ].filter(Boolean).join('\n'))
    .join('\n\n');
}

const event = firstDefined(payload?.event, payload?.type, payload?.data?.event, 'unknown');
const data = firstDefined(payload?.data, payload);
const key = firstDefined(data?.key, data?.message?.key, data?.messages?.[0]?.key, {});
const message = firstDefined(data?.message, data?.messages?.[0]?.message, {});
const remoteJid = firstDefined(key?.remoteJid, data?.remoteJid, '');
const fromMe = Boolean(firstDefined(key?.fromMe, data?.fromMe, false));
const isGroup = remoteJid.endsWith('@g.us');
const isStatus = remoteJid === 'status@broadcast';
const senderNumber = remoteJid.replace(/@.+$/, '').replace(/\D/g, '');
const text = normalizeText(message).trim();
const audio = extractAudio(message);
const isAudio = Boolean(audio.url || audio.base64);

if (fromMe || isGroup || isStatus) {
  return {
    json: {
      action: 'skipped',
      reason: 'self-group-or-status',
      event,
      remoteJid
    }
  };
}

if (!text && !isAudio) {
  return {
    json: {
      action: 'skipped',
      reason: 'no-text-or-audio',
      event,
      remoteJid
    }
  };
}

const openAiKey = process.env.OPENAI_API_KEY;
const evolutionApiKey = process.env.EVOLUTION_API_KEY;
const evolutionInstance = process.env.EVOLUTION_INSTANCE;
const evolutionServerUrl = process.env.EVOLUTION_SERVER_URL;
const wooCommerceBaseUrl = process.env.WOOCOMMERCE_BASE_URL;
const wooCommerceConsumerKey = process.env.WOOCOMMERCE_CONSUMER_KEY;
const wooCommerceConsumerSecret = process.env.WOOCOMMERCE_CONSUMER_SECRET;
const hasWooCommerceConfig = Boolean(wooCommerceBaseUrl && wooCommerceConsumerKey && wooCommerceConsumerSecret);

if (!openAiKey) {
  throw new Error('OPENAI_API_KEY is missing in the n8n environment');
}
if (!evolutionApiKey) {
  throw new Error('EVOLUTION_API_KEY is missing in the n8n environment');
}
if (!evolutionInstance) {
  throw new Error('EVOLUTION_INSTANCE is missing in the n8n environment');
}
if (!evolutionServerUrl) {
  throw new Error('EVOLUTION_SERVER_URL is missing in the n8n environment');
}

let promptText = text;
let transcription = null;

if (isAudio) {
  let audioBuffer;

  if (audio.base64) {
    const normalizedBase64 = audio.base64.includes(',')
      ? audio.base64.split(',').pop()
      : audio.base64;
    audioBuffer = Buffer.from(normalizedBase64, 'base64');
  } else {
    const audioResponse = await fetch(audio.url);
    if (!audioResponse.ok) {
      throw new Error(`Failed to download audio: ${audioResponse.status} ${audioResponse.statusText}`);
    }
    audioBuffer = Buffer.from(await audioResponse.arrayBuffer());
  }

  const formData = new FormData();
  const extension = audio.mimeType.includes('mpeg') ? 'mp3' : audio.mimeType.includes('mp4') ? 'm4a' : 'ogg';
  formData.append('file', new Blob([audioBuffer], { type: audio.mimeType }), `voice-note.${extension}`);
  formData.append('model', 'whisper-1');

  const transcriptionResponse = await fetch('https://api.openai.com/v1/audio/transcriptions', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${openAiKey}`
    },
    body: formData
  });

  if (!transcriptionResponse.ok) {
    const errorText = await transcriptionResponse.text();
    throw new Error(`Whisper transcription failed: ${transcriptionResponse.status} ${errorText}`);
  }

  const transcriptionPayload = await transcriptionResponse.json();
  transcription = transcriptionPayload.text?.trim() ?? '';
  promptText = transcription;
  console.log('[whatsapp-ai] transcription', { senderNumber, transcription });
}

if (!promptText) {
  return {
    json: {
      action: 'skipped',
      reason: 'empty-prompt-after-normalization',
      event,
      remoteJid
    }
  };
}

const productIntent = detectProductIntent(promptText);
let matchedProducts = [];
let businessContext = '';

if (productIntent && hasWooCommerceConfig) {
  matchedProducts = await fetchWooCommerceProducts(
    promptText,
    wooCommerceBaseUrl,
    wooCommerceConsumerKey,
    wooCommerceConsumerSecret
  );
  businessContext = formatProductContext(matchedProducts);
}

const systemPrompt = `You are a multilingual WhatsApp assistant.
Reply in the same language used by the customer.
Support Malayalam, Manglish, English, Hindi, Tamil, and Kannada.
Keep responses short, natural, and WhatsApp-friendly.
Do not use markdown.
Do not use formal business language unless user speaks formally.
If user sends Malayalam, reply in Malayalam.
If user sends Manglish, reply in Manglish.
If business context is provided, use only that business context for product facts and do not invent prices, stock, or URLs.`;

const userPrompt = businessContext
  ? `Customer message:
${promptText}

Business context:
${businessContext}

Use the business context when answering product questions. If no matching products were found, ask a short follow-up question.`
  : promptText;

const chatResponse = await fetch('https://api.openai.com/v1/chat/completions', {
  method: 'POST',
  headers: {
    Authorization: `Bearer ${openAiKey}`,
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({
    model: 'gpt-4o-mini',
    temperature: 0.6,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ]
  })
});

if (!chatResponse.ok) {
  const errorText = await chatResponse.text();
  throw new Error(`OpenAI reply generation failed: ${chatResponse.status} ${errorText}`);
}

const chatPayload = await chatResponse.json();
const replyText = chatPayload.choices?.[0]?.message?.content?.trim();

if (!replyText) {
  throw new Error('OpenAI returned an empty reply');
}

console.log('[whatsapp-ai] incoming', { senderNumber, promptText, productIntent, matchedProducts: matchedProducts.length });
console.log('[whatsapp-ai] reply', { senderNumber, replyText });

const sendResponse = await fetch(`${evolutionServerUrl}/message/sendText/${evolutionInstance}`, {
  method: 'POST',
  headers: {
    apikey: evolutionApiKey,
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({
    number: senderNumber,
    text: replyText
  })
});

const sendPayload = await sendResponse.json().catch(() => ({}));

if (!sendResponse.ok) {
  throw new Error(`Evolution sendText failed: ${sendResponse.status} ${JSON.stringify(sendPayload)}`);
}

return {
  json: {
    action: 'replied',
    event,
    remoteJid,
    senderNumber,
    promptText,
    transcription,
    productIntent,
    matchedProducts,
    replyText,
    evolutionResponse: sendPayload
  }
};
